func NewLuno(userConfig map[string]any) *Luno {
	p := newLuno()
	p.Init(userConfig)
	return p
}

func (this *Luno) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

// typed methods

/**
 * @method
 * @name luno#watchTrades
 * @description get the list of most recent trades for a particular symbol
 * @see https://www.luno.com/en/developers/api#tag/Streaming-API
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of    trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Luno) WatchTrades(symbol string, options ...ccxt.WatchTradesOptions) ([]ccxt.Trade, error) {

	opts := ccxt.WatchTradesOptionsStruct{}

	for _, opt := range options {
		opt(&opts)
	}
	r := <-this.WatchTradesAsync(symbol, opts.Since, opts.Limit, opts.Params)
	if r.Err != nil {
		return nil, r.Err
	}
	var res []ccxt.Trade = r.Value
	return res, nil
}

/**
 * @method
 * @name luno#watchOrderBook
 * @description watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://www.luno.com/en/developers/api#tag/Streaming-API
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {objectConstructor} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.type] accepts l2 or l3 for level 2 or level 3 order book
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Luno) WatchOrderBook(symbol string, options ...ccxt.WatchOrderBookOptions) (ccxt.OrderBook, error) {

	opts := ccxt.WatchOrderBookOptionsStruct{}

	for _, opt := range options {
		opt(&opts)
	}
	r := <-this.WatchOrderBookAsync(symbol, opts.Limit, opts.Params)
	if r.Err != nil {
		return ccxt.OrderBook{}, r.Err
	}
	var res ccxt.OrderBook = ccxt.NewOrderBookFromWs(r.Value)
	return res, nil
}
